function normalizeReading(input) {
  if (!input || typeof input !== 'object' || Array.isArray(input)) throw new Error('Leitura precisa ser um objeto JSON.');
  const result = {};
  for (const name of ['lixeira', 'setor', 'compartimento']) {
    if (typeof input[name] !== 'string' || !input[name].trim() || input[name].length > 100) {
      throw new Error(`Campo ${name} ausente ou invalido.`);
    }
    result[name] = input[name].trim();
  }
  for (const [name, max] of [['massa_kg', 10000], ['distancia_cm', 1000], ['ocupacao_pct', 100]]) {
    if (typeof input[name] !== 'number' || !Number.isFinite(input[name]) || input[name] < 0 || input[name] > max) {
      throw new Error(`Campo ${name} precisa ser um numero entre 0 e ${max}.`);
    }
    result[name] = input[name];
  }
  if (typeof input.simulado !== 'boolean') throw new Error('Campo simulado precisa ser true ou false.');
  result.simulado = input.simulado;
  result.uptime_ms = Number.isSafeInteger(input.uptime_ms) && input.uptime_ms >= 0 ? input.uptime_ms : null;
  result.coletar = result.massa_kg >= 8 || result.ocupacao_pct >= 80;
  result.status = result.coletar ? 'coletar' : result.ocupacao_pct >= 70 ? 'acompanhar' : 'normal';
  return result;
}
try {
    const input = typeof msg.payload === 'string' ? JSON.parse(msg.payload) : msg.payload;
    msg.payload = normalizeReading(input);
    const parts = String(msg.topic || '').split('/');
    if (parts.length === 3 && parts[0] === 'ecobin' && parts[2] === 'telemetria' && parts[1] !== msg.payload.lixeira) throw new Error('Lixeira nao corresponde ao topico MQTT.');
    flow.set('ecobin_ultima_leitura', { ...msg.payload, recebido_em: new Date().toISOString() });
    node.status({fill:'green',shape:'dot',text:msg.payload.lixeira+' / '+msg.payload.ocupacao_pct.toFixed(0)+'% / '+msg.payload.massa_kg.toFixed(2)+' kg'});
    return msg;
} catch (error) {
    node.error('Telemetria rejeitada: ' + error.message, msg);
    return null;
}

const ok = msg.statusCode === 201 && msg.payload?.ok === true;
flow.set('ecobin_http', {ok,status:msg.statusCode || 0,atualizado_em:new Date().toISOString()});
node.status({fill:ok?'green':'red',shape:'dot',text:ok?'gravado / ID '+msg.payload.id:'erro HTTP '+msg.statusCode});
if (!ok) node.error('Falha ao salvar leitura. Confira o servico site e o token de ingestao no ambiente.', msg);
return null;

// O Chat ID e preenchido no no Change anterior. Token fica nas credenciais do bot.
const chatId = String(msg.telegramChatId || '').trim();
if (!/^-?\d+$/.test(chatId)) {
    flow.set('ecobin_telegram_configurado', false);
    node.status({ fill: 'yellow', shape: 'ring', text: 'preencher Chat ID' });
    return null;
}
flow.set('ecobin_telegram_configurado', true);
if (msg.telegramTeste === true) {
    msg.payload = {
        chatId,
        type: 'message',
        content: 'EcoBin / ScriptBoys\nTeste de conexao do Node-RED com o Telegram concluido.'
    };
    delete msg.telegramChatId;
    return msg;
}

const r = msg.payload;
const key = JSON.stringify([r.lixeira, r.setor, r.compartimento]);
const cache = flow.get('ecobin_alertas') || {};
const now = Date.now();
const state = cache[key] || { ativo: false, notificado: false, tentativa: 0, ciclo: 0 };
if (!state.ativo && (r.massa_kg >= 8 || r.ocupacao_pct >= 80)) {
    state.ativo = true;
    state.notificado = false;
    state.tentativa = 0;
    state.ciclo = now;
}
if (state.ativo && r.massa_kg <= 7 && r.ocupacao_pct <= 70) {
    state.ativo = false;
    state.notificado = false;
    state.tentativa = 0;
}
cache[key] = state;
flow.set('ecobin_alertas', cache);
if (!state.ativo) {
    node.status({ fill: 'green', shape: 'dot', text: 'nivel normal' });
    return null;
}
if (state.notificado || now - state.tentativa < 60000) {
    node.status({ fill: 'yellow', shape: 'dot', text: state.notificado ? 'alerta ja entregue' : 'aguardando envio / nova tentativa em 60 s' });
    return null;
}
state.tentativa = now;
flow.set('ecobin_alertas', cache);
msg.ecobinAlertaKey = key;
msg.ecobinAlertaCiclo = state.ciclo;
msg.payload = {
    chatId,
    type: 'message',
    content: [
        'ECOBIN - ALERTA DE COLETA',
        '',
        'Setor: ' + r.setor,
        'Lixeira: ' + r.lixeira,
        'Compartimento: ' + r.compartimento,
        'Ocupacao: ' + r.ocupacao_pct.toFixed(1) + '%',
        'Massa: ' + r.massa_kg.toFixed(2) + ' kg',
        '',
        'Acao: programar coleta interna.',
        r.simulado ? 'Dados simulados do prototipo.' : 'Leitura dos sensores.',
        'Recebido: ' + new Date(now).toLocaleString('pt-BR', { timeZone: 'America/Sao_Paulo' })
    ].join('\n')
};
delete msg.telegramChatId;
node.status({ fill: 'blue', shape: 'dot', text: 'enviando alerta' });
return msg;

if (msg.ecobinAlertaKey) {
    const cache = flow.get('ecobin_alertas') || {};
    const state = cache[msg.ecobinAlertaKey];
    if (state && state.ativo && state.ciclo === msg.ecobinAlertaCiclo) {
        state.notificado = true;
        flow.set('ecobin_alertas', cache);
    }
}
flow.set('ecobin_ultimo_telegram', Date.now());
msg.payload = { sucesso: true, origem: 'Telegram', enviado_em: new Date().toISOString(), messageId: msg.payload?.sentMessageId };
return msg;

const error = msg.error;
const text = (typeof error === 'string' ? error : error?.message) || 'Falha na integracao.';
msg = {payload:{erro:text.replace(/bot\d+:[A-Za-z0-9_-]+/g,'bot<token-omitido>'),origem:error?.source?.name || 'EcoBin',horario:new Date().toISOString()}};
return msg;

const p = msg.payload;
if (!p || p.type !== 'message' || typeof p.content !== 'string' || !/^\/start(?:@\w+)?(?:\s|$)/.test(p.content.trim())) return null;
const chatId = String(p.chatId || '');
if (!/^-?\d+$/.test(chatId)) return null;
const chat = msg.originalMessage?.chat || {};
const chats = flow.get('ecobin_chats') || [];
const entry = { chatId, tipo: chat.type || 'desconhecido', nome: chat.title || chat.first_name || '', recebido_em: new Date().toISOString() };
const saved = [entry, ...chats.filter(c => c.chatId !== chatId)].slice(0, 30);
flow.set('ecobin_chats', saved);
flow.set('ecobin_ultimo_start', entry.recebido_em);
node.status({ fill: 'green', shape: 'dot', text: '/start recebido' });
// A resposta vai somente ao chat que iniciou a conversa. O destino dos alertas continua manual.
const reply = { payload: {
    chatId, type: 'message',
    content: 'EcoBin conectado ao Node-RED.\n\nSeu Chat ID: ' + chatId + '\n\nO destino dos alertas e configurado em TELEGRAM_CHAT_ID no ambiente da VM.'
} };
return [reply, { payload: { chats: saved, instrucao: 'Copie o chatId desejado para o no laranja e faca Deploy.' } }];

const chats = flow.get('ecobin_chats') || [];
msg.payload = chats.length ? {
    chats,
    instrucao: 'Copie o chatId desejado para o no PREENCHER: Chat ID do Telegram e faca Deploy.'
} : {
    aviso: 'Envie /start novamente ao bot correto. O receptor precisa estar implantado antes da mensagem.',
    bot: flow.get('ecobin_bot_info') || null
};
return msg;
